import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Versión de Documentos y Notas de Mantenimiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/0099-文档版本与维护说明.md","filePath":"es/0099-文档版本与维护说明.md"}'),r={name:"es/0099-文档版本与维护说明.md"};function s(d,e,t,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="version-de-documentos-y-notas-de-mantenimiento" tabindex="-1">Versión de Documentos y Notas de Mantenimiento <a class="header-anchor" href="#version-de-documentos-y-notas-de-mantenimiento" aria-label="Permalink to &quot;Versión de Documentos y Notas de Mantenimiento&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>99</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>gestión de versiones, notas de mantenimiento, normas de documentos, registro de actualizaciones, mantenimiento de la configuración</td></tr></tbody></table><h2 id="i-panorama-del-sistema-documental" tabindex="-1">I. Panorama del sistema documental <a class="header-anchor" href="#i-panorama-del-sistema-documental" aria-label="Permalink to &quot;I. Panorama del sistema documental&quot;">​</a></h2><p>El sistema de configuración de la Civilización Simbiótica del Ancla se compone de 100 documentos Markdown, numerados del 00 al 99, divididos en diez grandes módulos, con 10 documentos en cada módulo. El sistema documental toma SPEC.md (Especificación de Generación de Documentos) como restricción estricta, toma «00-Heng Yuan Zhou: Panorama del Cosmos» como esquema general, desarrolla en detalle los documentos de cada módulo desde distintas dimensiones y, finalmente, utiliza los documentos de apéndice 90-99 para la indexación, síntesis y ordenación. Todo el sistema documental constituye una base de conocimiento de configuración completa, lógicamente coherente, claramente jerarquizada y mutuamente referenciada.</p><p>El diseño del sistema documental sigue tres grandes principios: «modularidad, estructuración y extensibilidad». La modularidad significa que cada documento se centra en un tema específico y constituye un artículo independiente; la estructuración significa que todos los documentos siguen una especificación de formato unificada, facilitando la lectura y la búsqueda; la extensibilidad significa que el sistema documental reserva un amplio margen de expansión, permitiendo mejorar continuamente la configuración mediante la revisión de los documentos existentes y la adición de nuevos contenidos.</p><h2 id="ii-reglas-de-numeracion-de-versiones" tabindex="-1">II. Reglas de numeración de versiones <a class="header-anchor" href="#ii-reglas-de-numeracion-de-versiones" aria-label="Permalink to &quot;II. Reglas de numeración de versiones&quot;">​</a></h2><p>El sistema documental adopta una regla de numeración de versiones de tres niveles «versión principal.versión menor.número de revisión»:</p><table tabindex="0"><thead><tr><th>Nivel de versión</th><th>Regla de numeración</th><th>Condición de activación</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Versión principal</td><td>Se incrementa a partir de 1</td><td>Ajuste arquitectónico mayor del sistema documental, como la redistribución de módulos o el cambio de la configuración central</td><td>v1.0 → v2.0</td></tr><tr><td>Versión menor</td><td>Se incrementa a partir de 0</td><td>Revisión sustancial del contenido central de un documento, o adición de contenido de configuración importante</td><td>v1.0 → v1.1</td></tr><tr><td>Número de revisión</td><td>Se incrementa a partir de 0</td><td>Modificaciones no sustanciales como correcciones de texto, ajustes de formato y unificación de terminología</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>La versión global actual del sistema documental es v1.0, es decir, la primera publicación completa. Cada documento registra su propio número de versión en su bloque de información documental, y el número de versión global del sistema documental se registra de manera unificada en este documento.</p><h2 id="iii-repaso-de-las-especificaciones-de-formato-de-los-documentos" tabindex="-1">III. Repaso de las especificaciones de formato de los documentos <a class="header-anchor" href="#iii-repaso-de-las-especificaciones-de-formato-de-los-documentos" aria-label="Permalink to &quot;III. Repaso de las especificaciones de formato de los documentos&quot;">​</a></h2><p>Todos los documentos deben seguir las siguientes especificaciones de formato unificadas (véase SPEC.md para las especificaciones detalladas):</p><h3 id="_3-1-denominacion-de-archivos" tabindex="-1">3.1 Denominación de archivos <a class="header-anchor" href="#_3-1-denominacion-de-archivos" aria-label="Permalink to &quot;3.1 Denominación de archivos&quot;">​</a></h3><p>El formato del nombre de archivo es <code>XX-Título del documento.md</code>, donde XX es un número de dos dígitos del 00 al 99, y el título está en chino sin espacios.</p><h3 id="_3-2-estructura-del-documento" tabindex="-1">3.2 Estructura del documento <a class="header-anchor" href="#_3-2-estructura-del-documento" aria-label="Permalink to &quot;3.2 Estructura del documento&quot;">​</a></h3><p>Cada documento debe contener los siguientes elementos estructurales:</p><ol><li><strong>Título de nivel uno</strong>: el título del documento (coherente con el nombre del archivo)</li><li><strong>Bloque de información del documento</strong>: una tabla de número, módulo y palabras clave centrales (3-5)</li><li><strong>Cuerpo principal</strong>: al menos 3 secciones con títulos de nivel dos, utilizando elementos estructurados como listas y tablas</li><li><strong>Conclusión</strong>: un breve párrafo de síntesis</li><li><strong>Documentos relacionados</strong>: lista de 2-3 números y nombres de documentos relacionados</li></ol><h3 id="_3-3-requisito-de-extension" tabindex="-1">3.3 Requisito de extensión <a class="header-anchor" href="#_3-3-requisito-de-extension" aria-label="Permalink to &quot;3.3 Requisito de extensión&quot;">​</a></h3><p>El cuerpo principal de cada documento no debe ser inferior a 800 caracteres (excluyendo títulos y metainformación).</p><h3 id="_3-4-estilo-de-redaccion" tabindex="-1">3.4 Estilo de redacción <a class="header-anchor" href="#_3-4-estilo-de-redaccion" aria-label="Permalink to &quot;3.4 Estilo de redacción&quot;">​</a></h3><ul><li>Estilo serio y sistemático de documento de configuración, similar a una enciclopedia/recopilación de configuración</li><li>Uso de términos unificados como «Universo Hengyuan», «Ancla» y «Simbiosis»</li><li>Las nuevas configuraciones añadidas deben ser lógicamente coherentes con la configuración existente y ajustarse al principio de «La Realidad como Fundamento, mejora mediante leyes»</li></ul><h2 id="iv-organizacion-de-mantenimiento-y-responsabilidades" tabindex="-1">IV. Organización de mantenimiento y responsabilidades <a class="header-anchor" href="#iv-organizacion-de-mantenimiento-y-responsabilidades" aria-label="Permalink to &quot;IV. Organización de mantenimiento y responsabilidades&quot;">​</a></h2><h3 id="_4-1-comite-de-mantenimiento-de-la-configuracion" tabindex="-1">4.1 Comité de Mantenimiento de la Configuración <a class="header-anchor" href="#_4-1-comite-de-mantenimiento-de-la-configuracion" aria-label="Permalink to &quot;4.1 Comité de Mantenimiento de la Configuración&quot;">​</a></h3><p>El Comité de Mantenimiento de la Configuración es el órgano supremo de mantenimiento del sistema documental, compuesto por creadores veteranos de configuración, expertos en verificación lógica y representantes de los usuarios. Sus responsabilidades centrales incluyen:</p><ul><li>Aprobar la arquitectura global del sistema documental y los planes de revisión mayor</li><li>Revisar los cambios importantes de configuración para garantizar la coherencia con la configuración central</li><li>Arbitrar las disputas de configuración y proporcionar interpretaciones autorizadas</li><li>Organizar periódicamente autoverificaciones exhaustivas de la coherencia de la configuración</li><li>Publicar las actualizaciones de versión global del sistema documental</li></ul><h3 id="_4-2-mantenedores-de-modulos" tabindex="-1">4.2 Mantenedores de módulos <a class="header-anchor" href="#_4-2-mantenedores-de-modulos" aria-label="Permalink to &quot;4.2 Mantenedores de módulos&quot;">​</a></h3><p>Cada módulo designa un mantenedor de módulo, responsable del mantenimiento diario de los 10 documentos de ese módulo. Sus responsabilidades incluyen:</p><ul><li>Realizar el seguimiento de la coherencia de la configuración de los documentos del módulo</li><li>Revisar las solicitudes de revisión de los documentos del módulo</li><li>Coordinar las referencias cruzadas entre los documentos del módulo</li><li>Recopilar los comentarios y sugerencias de los usuarios sobre el contenido del módulo</li><li>Informar periódicamente del estado de mantenimiento del módulo al Comité de Mantenimiento de la Configuración</li></ul><h3 id="_4-3-creadores-de-documentos" tabindex="-1">4.3 Creadores de documentos <a class="header-anchor" href="#_4-3-creadores-de-documentos" aria-label="Permalink to &quot;4.3 Creadores de documentos&quot;">​</a></h3><p>Cualquier creador cualificado puede participar en la creación y revisión de documentos. Las responsabilidades de los creadores incluyen:</p><ul><li>Crear o revisar documentos conforme a las especificaciones de formato</li><li>Garantizar que el contenido creado supere la comprobación de la Lista de Autoverificación de Contradicciones de Configuración</li><li>Adjuntar una descripción detallada de la revisión al presentarla</li><li>Cooperar con el trabajo de revisión de los mantenedores y del Comité</li></ul><h2 id="v-proceso-de-revision" tabindex="-1">V. Proceso de revisión <a class="header-anchor" href="#v-proceso-de-revision" aria-label="Permalink to &quot;V. Proceso de revisión&quot;">​</a></h2><h3 id="_5-1-proceso-de-revision-ordinario" tabindex="-1">5.1 Proceso de revisión ordinario <a class="header-anchor" href="#_5-1-proceso-de-revision-ordinario" aria-label="Permalink to &quot;5.1 Proceso de revisión ordinario&quot;">​</a></h3><ol><li><strong>Presentar una solicitud</strong>: el creador presenta una solicitud de revisión al mantenedor del módulo, incluyendo el número del documento a revisar, la descripción del contenido de la revisión y los motivos de la revisión.</li><li><strong>Revisión del módulo</strong>: el mantenedor del módulo revisa el contenido de la revisión, centrándose en las especificaciones de formato y la coherencia dentro del módulo. Tras la aprobación, se presenta al Comité de Mantenimiento de la Configuración.</li><li><strong>Aprobación del Comité</strong>: el Comité de Mantenimiento de la Configuración realiza la aprobación final del contenido de la revisión, centrándose en la coherencia entre módulos y la coherencia de la configuración central.</li><li><strong>Ejecución de la revisión</strong>: tras la aprobación, el mantenedor del módulo o el autor original ejecuta la revisión del documento.</li><li><strong>Actualización de versión</strong>: tras completarse la revisión, actualizar el número de versión del documento y registrarlo en el registro de actualizaciones de este documento.</li><li><strong>Sincronización de documentos relacionados</strong>: si el contenido de la revisión afecta a otros documentos, los documentos relacionados deben revisarse en sincronización.</li></ol><h3 id="_5-2-proceso-de-revision-de-emergencia" tabindex="-1">5.2 Proceso de revisión de emergencia <a class="header-anchor" href="#_5-2-proceso-de-revision-de-emergencia" aria-label="Permalink to &quot;5.2 Proceso de revisión de emergencia&quot;">​</a></h3><p>Para situaciones de emergencia en las que se descubran contradicciones o errores graves de configuración, puede iniciarse el proceso de revisión de emergencia:</p><ol><li><strong>Informe de emergencia</strong>: el descubridor informa inmediatamente del problema al Comité de Mantenimiento de la Configuración.</li><li><strong>Aprobación rápida</strong>: el Comité completa la aprobación de emergencia en 24 horas y proporciona un plan de revisión.</li><li><strong>Ejecución de la revisión</strong>: designar a una persona dedicada para ejecutar la revisión de inmediato.</li><li><strong>Registro retrospectivo</strong>: tras completarse la revisión, registrar retrospectivamente la solicitud de revisión y los registros de revisión.</li></ol><h3 id="_5-3-revision-global-periodica" tabindex="-1">5.3 Revisión global periódica <a class="header-anchor" href="#_5-3-revision-global-periodica" aria-label="Permalink to &quot;5.3 Revisión global periódica&quot;">​</a></h3><p>El Comité de Mantenimiento de la Configuración organiza una vez al año una revisión global del sistema documental, que incluye:</p><ul><li>Una autoverificación exhaustiva de la coherencia de la configuración</li><li>El tratamiento centralizado de los comentarios de los usuarios</li><li>La unificación y actualización del sistema terminológico</li><li>La actualización sincronizada de los documentos de índice</li><li>La comprobación y corrección unificadas de los formatos de los documentos</li></ul><h2 id="vi-registro-de-actualizaciones" tabindex="-1">VI. Registro de actualizaciones <a class="header-anchor" href="#vi-registro-de-actualizaciones" aria-label="Permalink to &quot;VI. Registro de actualizaciones&quot;">​</a></h2><h3 id="v1-0-primera-publicacion-completa" tabindex="-1">v1.0 (Primera publicación completa) <a class="header-anchor" href="#v1-0-primera-publicacion-completa" aria-label="Permalink to &quot;v1.0 (Primera publicación completa)&quot;">​</a></h3><ul><li>Finalización de la creación y publicación de los 100 documentos</li><li>Establecimiento de la arquitectura completa del sistema documental y de las especificaciones de formato</li><li>Finalización de la cobertura de los contenidos de los diez grandes módulos</li><li>Establecimiento del sistema de índices de apéndice (diccionario de terminología, índice de sistemas, índice jurídico, cronología, registro de las Diez Mil Razas, figuras y organizaciones, FAQ, lista de autoverificación, sugerencias de expansión, notas de versión)</li></ul><h3 id="zona-de-registro-de-actualizaciones-de-versiones-posteriores" tabindex="-1">Zona de registro de actualizaciones de versiones posteriores <a class="header-anchor" href="#zona-de-registro-de-actualizaciones-de-versiones-posteriores" aria-label="Permalink to &quot;Zona de registro de actualizaciones de versiones posteriores&quot;">​</a></h3><p>(Los contenidos de actualización de las versiones posteriores se añadirán aquí, incluidos el número de versión, la fecha de publicación y el resumen de los principales contenidos de la actualización)</p><h2 id="vii-especificaciones-de-citacion-y-referencias-cruzadas-de-los-documentos" tabindex="-1">VII. Especificaciones de citación y referencias cruzadas de los documentos <a class="header-anchor" href="#vii-especificaciones-de-citacion-y-referencias-cruzadas-de-los-documentos" aria-label="Permalink to &quot;VII. Especificaciones de citación y referencias cruzadas de los documentos&quot;">​</a></h2><h3 id="_7-1-citas-internas" tabindex="-1">7.1 Citas internas <a class="header-anchor" href="#_7-1-citas-internas" aria-label="Permalink to &quot;7.1 Citas internas&quot;">​</a></h3><p>Las referencias cruzadas entre documentos utilizan el formato «número de documento-título del documento», por ejemplo, «véase el documento 84 «Marco General de los Protocolos Arqueológicos»». Al citar, debe garantizarse que el documento citado existe realmente y que el número y el título son correctos.</p><h3 id="_7-2-citas-terminologicas" tabindex="-1">7.2 Citas terminológicas <a class="header-anchor" href="#_7-2-citas-terminologicas" aria-label="Permalink to &quot;7.2 Citas terminológicas&quot;">​</a></h3><p>En el primer uso de un término central, puede indicarse la referencia a la entrada correspondiente del documento 90 «El Diccionario de Terminología». En los usos posteriores del mismo término no es necesario repetir la referencia.</p><h3 id="_7-3-citas-externas" tabindex="-1">7.3 Citas externas <a class="header-anchor" href="#_7-3-citas-externas" aria-label="Permalink to &quot;7.3 Citas externas&quot;">​</a></h3><p>Si es necesario citar materiales reales u obras de ficción ajenos al sistema de configuración, debe indicarse la fuente y aclararse explícitamente que dicha cita constituye material de referencia bajo el principio de «La Realidad como Fundamento», y no representa la adopción completa de su contenido por parte del sistema de configuración.</p><h2 id="viii-mecanismos-de-aseguramiento-de-la-calidad" tabindex="-1">VIII. Mecanismos de aseguramiento de la calidad <a class="header-anchor" href="#viii-mecanismos-de-aseguramiento-de-la-calidad" aria-label="Permalink to &quot;VIII. Mecanismos de aseguramiento de la calidad&quot;">​</a></h2><h3 id="_8-1-autoverificacion-de-contradicciones-de-configuracion" tabindex="-1">8.1 Autoverificación de contradicciones de configuración <a class="header-anchor" href="#_8-1-autoverificacion-de-contradicciones-de-configuracion" aria-label="Permalink to &quot;8.1 Autoverificación de contradicciones de configuración&quot;">​</a></h3><p>Todos los documentos recién creados y revisados deben superar todos los puntos de comprobación de la Lista de Autoverificación de Contradicciones de Configuración (documento 97), que incluye más de 40 comprobaciones en tres grandes categorías: coherencia de la configuración central, coherencia lógica entre módulos y especificaciones de formato documental.</p><h3 id="_8-2-revision-cruzada" tabindex="-1">8.2 Revisión cruzada <a class="header-anchor" href="#_8-2-revision-cruzada" aria-label="Permalink to &quot;8.2 Revisión cruzada&quot;">​</a></h3><p>Cada documento debe, antes de su publicación oficial, pasar una revisión cruzada de al menos otro creador, centrada en la coherencia lógica entre módulos y la uniformidad terminológica.</p><h3 id="_8-3-mecanismo-de-comentarios-de-los-usuarios" tabindex="-1">8.3 Mecanismo de comentarios de los usuarios <a class="header-anchor" href="#_8-3-mecanismo-de-comentarios-de-los-usuarios" aria-label="Permalink to &quot;8.3 Mecanismo de comentarios de los usuarios&quot;">​</a></h3><p>El sistema documental establece canales de comentarios de los usuarios; los usuarios pueden presentar comentarios por las siguientes vías:</p><ul><li>Informar de contradicciones de configuración y errores lógicos</li><li>Plantear problemas de terminología no unificada</li><li>Sugerir la complementación o revisión de contenidos específicos</li><li>Señalar errores de formato y de texto</li></ul><p>Todos los comentarios son tratados por categorías por los mantenedores de módulos, y los comentarios importantes se presentan al Comité de Mantenimiento de la Configuración para su deliberación.</p><h3 id="_8-4-informe-trimestral-de-coherencia" tabindex="-1">8.4 Informe trimestral de coherencia <a class="header-anchor" href="#_8-4-informe-trimestral-de-coherencia" aria-label="Permalink to &quot;8.4 Informe trimestral de coherencia&quot;">​</a></h3><p>El Comité de Mantenimiento de la Configuración publica cada trimestre un «Informe de Coherencia de la Configuración», cuyo contenido incluye:</p><ul><li>Las contradicciones de configuración descubiertas en el trimestre y su tratamiento</li><li>Las estadísticas de revisiones documentales del trimestre</li><li>Los avances de la unificación terminológica</li><li>El tratamiento de los comentarios de los usuarios</li><li>El plan de mantenimiento del trimestre siguiente</li></ul><h2 id="ix-almacenamiento-y-distribucion-de-los-documentos" tabindex="-1">IX. Almacenamiento y distribución de los documentos <a class="header-anchor" href="#ix-almacenamiento-y-distribucion-de-los-documentos" aria-label="Permalink to &quot;IX. Almacenamiento y distribución de los documentos&quot;">​</a></h2><h3 id="_9-1-formato-de-almacenamiento" tabindex="-1">9.1 Formato de almacenamiento <a class="header-anchor" href="#_9-1-formato-de-almacenamiento" aria-label="Permalink to &quot;9.1 Formato de almacenamiento&quot;">​</a></h3><p>Todos los documentos se almacenan en formato Markdown (.md), garantizando la legibilidad multiplataforma y la comodidad de la gestión de versiones. Los documentos utilizan codificación UTF-8, compatible con el chino y los caracteres especiales.</p><h3 id="_9-2-estructura-de-directorios" tabindex="-1">9.2 Estructura de directorios <a class="header-anchor" href="#_9-2-estructura-de-directorios" aria-label="Permalink to &quot;9.2 Estructura de directorios&quot;">​</a></h3><p>Los documentos se almacenan de manera unificada en el directorio <code>anchor-docs/</code>, con nombres de archivo en el formato <code>XX-Título del documento.md</code>. SPEC.md, como archivo de especificaciones, también se almacena en el mismo directorio.</p><h3 id="_9-3-gestion-de-versiones" tabindex="-1">9.3 Gestión de versiones <a class="header-anchor" href="#_9-3-gestion-de-versiones" aria-label="Permalink to &quot;9.3 Gestión de versiones&quot;">​</a></h3><p>Se recomienda utilizar sistemas de control de versiones como Git para la gestión de versiones de los documentos, adjuntando mensajes de commit detallados que registren el contenido y los motivos de cada revisión presentada.</p><h3 id="_9-4-modos-de-distribucion" tabindex="-1">9.4 Modos de distribución <a class="header-anchor" href="#_9-4-modos-de-distribucion" aria-label="Permalink to &quot;9.4 Modos de distribución&quot;">​</a></h3><p>El sistema documental puede distribuirse de las siguientes maneras:</p><ul><li>Empaquetado en un archivo ZIP para su descarga</li><li>Despliegue como sitio web estático para su consulta en línea</li><li>Conversión a formato PDF o EPUB para su lectura</li><li>Importación en sistemas de bases de conocimiento para su gestión estructurada</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Versión de Documentos y Notas de Mantenimiento es la «constitución administrativa» del sistema de configuración de la Civilización Simbiótica del Ancla. Establece las reglas de versión, la organización de mantenimiento, el proceso de revisión, los mecanismos de aseguramiento de la calidad y los modos de almacenamiento y distribución del sistema documental, garantizando que este vasto sistema de configuración compuesto por 100 documentos pueda mantener siempre el orden y la coherencia en el curso de su crecimiento continuo. Un buen sistema de configuración requiere no solo un contenido excelente, sino también un mecanismo de mantenimiento sólido que garantice su desarrollo saludable a largo plazo. Este documento es el soporte central de ese mecanismo.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Lista de Autoverificación de Contradicciones de Configuración)</li><li>90-术语词典 (El Diccionario de Terminología)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Panorama del Cosmos)</li></ul>',77)])])}const h=a(r,[["render",s]]);export{p as __pageData,h as default};
